mapper.select:
SELECT 
  FROM tb_kms_operations
 WHERE institution_id = #{institutionId}
 ORDER BY created_at DESC, id DESC
 LIMIT #{limit}

mapper.update:
UPDATE tb_kms_operations
   SET owner = #{owner}, lease_until = #{leaseUntil}
 WHERE id = #{id}
   AND status IN ('PREPARED', 'UNCONFIRMED', 'RECORDED')
   AND (owner IS NULL OR lease_until < #{now})

UPDATE tb_kms_operations
   SET lease_until = #{leaseUntil}, last_call_at = #{now}
 WHERE id = #{id}
   AND owner = #{owner}
   AND lease_until >= #{now}
   AND status = #{status}

UPDATE tb_kms_operations
   SET owner = NULL, lease_until = NULL
 WHERE id = #{id}
   AND owner = #{owner}
